""" Script d'entrée unique pour lancer l'ingestion et l'application des corporate actions (équivalent à 'python -m corporate_actions run'). """ from corporate_actions.cli import _run_all, _build_parser import logging import sys
def main(): logging.basicConfig( level=logging.INFO, format="%(asctime)s %(levelname)-8s %(name)s -- %(message)s", ) parser = _build_parser() args = parser.parse_args() # Force la commande 'run' même si non précisée if not hasattr(args, 'command') or args.command != 'run': args.command = 'run' _run_all(args)
if __name__ == "__main__": main()

"""ihm/pages/db_admin.py — Administration et purge sélective de la base."""
from __future__ import annotations

import streamlit as st

from ihm.components.db_controls import render_db_connection_form, render_db_unavailable
from ihm.pages import run_page_if_standalone
from ihm.services.db import get_engine, get_runtime_db_config, reset_db_caches
from ihm.services.db_admin import (
	FUNCTIONALITY_GROUP_ORDER,
	PROTECTED_TABLES,
	TableCatalogEntry,
	build_table_purge_plan,
	execute_table_purge,
	list_grouped_tables,
	load_database_table_snapshot,
)

CHECKBOX_PREFIX = "ihm_db_admin_table_"
CONFIRM_PURGE_KEY = "ihm_db_admin_confirm_purge"


def _checkbox_key(table_name: str) -> str:
	return f"{CHECKBOX_PREFIX}{table_name}"


def _set_selection(grouped_tables: dict[str, list[TableCatalogEntry]], *, value: bool) -> None:
	for entries in grouped_tables.values():
		for entry in entries:
			if entry.exists_in_database and not entry.protected:
				st.session_state[_checkbox_key(entry.table_name)] = value


def _render_group(group_name: str, entries: list[TableCatalogEntry]) -> None:
	purgeable_count = sum(1 for entry in entries if entry.exists_in_database and not entry.protected)
	with st.expander(f"{group_name} ({len(entries)} tables, {purgeable_count} purgeables)", expanded=True):
		for entry in entries:
			cols = st.columns([3.6, 1.5, 1.4, 2.5])
			disabled = bool(entry.protected or not entry.exists_in_database)
			help_text = None
			if entry.protected:
				help_text = "Table protégée : elle reste visible mais ne peut pas être vidée depuis l'IHM."
			elif not entry.exists_in_database:
				help_text = "Table attendue dans le référentiel projet mais absente de la base connectée."

			cols[0].checkbox(
				entry.table_name,
				key=_checkbox_key(entry.table_name),
				disabled=disabled,
				help=help_text,
			)

			row_estimate = "—" if entry.row_estimate is None else f"≈ {entry.row_estimate:,}".replace(",", " ")
			cols[1].markdown(f"**Lignes**  \n{row_estimate}")
			cols[2].markdown(
				"**Statut**  \n"
				+ (
					" protégée"
					if entry.protected
					else " présente"
					if entry.exists_in_database
					else "⚪ absente"
				)
			)
			cols[3].markdown(
				"**Action**  \n"
				+ (
					"exclue"
					if entry.protected
					else "DELETE FROM"
					if entry.exists_in_database
					else "indisponible"
				)
			)


def render() -> None:
	st.header("️ Administration DB")
	st.caption(
		"Catalogue des tables groupées par fonctionnalité. Le bouton de purge vide uniquement les données des tables cochées ; aucune table n'est supprimée."
	)
	st.warning(
		"⚠️ Les tables `stock_metadata`, `stock_bars` et `stock_bars_daily` sont explicitement protégées et ne peuvent pas être vidées depuis cette page."
	)

	with st.expander("️ Connexion DB", expanded=False):
		render_db_connection_form("db_admin_connection_form", show_host_fields=True)

	engine = get_engine()
	if engine is None:
		render_db_unavailable("Administration DB", form_key="db_admin_inline_connection_form")
		return

	snapshot = load_database_table_snapshot(engine)
	grouped_tables = list_grouped_tables(snapshot)
	active_db = get_runtime_db_config()

	st.info(
		f"Base active : `{active_db.get('name')}` sur `{active_db.get('host')}` — source `{active_db.get('source')}`."
	)

	action_col1, action_col2, action_col3 = st.columns(3)
	if action_col1.button("Sélectionner toutes les tables purgeables", use_container_width=True):
		_set_selection(grouped_tables, value=True)
		st.rerun()
	if action_col2.button("Tout désélectionner", use_container_width=True):
		_set_selection(grouped_tables, value=False)
		st.rerun()
	if action_col3.button("Rafraîchir le catalogue", use_container_width=True):
		reset_db_caches(clear_errors=False)
		st.rerun()

	for group_name in FUNCTIONALITY_GROUP_ORDER:
		entries = grouped_tables.get(group_name)
		if entries:
			_render_group(group_name, entries)
	for group_name, entries in grouped_tables.items():
		if group_name not in FUNCTIONALITY_GROUP_ORDER:
			_render_group(group_name, entries)

	selected_tables = [
		entry.table_name
		for entries in grouped_tables.values()
		for entry in entries
		if st.session_state.get(_checkbox_key(entry.table_name), False)
	]

	st.divider()
	st.subheader(" Plan de vidage")

	if not selected_tables:
		st.info("Cochez une ou plusieurs tables purgeables pour afficher le plan SQL correspondant.")
		return

	plan = build_table_purge_plan(selected_tables, snapshot)

	if plan.protected_tables:
		st.warning(
			"Tables protégées ignorées : " + ", ".join(f"`{table_name}`" for table_name in plan.protected_tables)
		)

	if plan.missing_tables:
		st.error(
			"Tables absentes dans la base connectée : " + ", ".join(f"`{table_name}`" for table_name in plan.missing_tables)
		)

	if plan.blocked_by_dependencies:
		st.error(
			"Certaines suppressions seraient bloquées par des tables filles non sélectionnées. Sélectionnez aussi les dépendances listées ci-dessous avant de lancer le vidage."
		)
		for table_name, dependent_tables in plan.blocked_by_dependencies.items():
			st.markdown(
				f"- `{table_name}` dépend encore de : {', '.join(f'`{child_table}`' for child_table in dependent_tables)}"
			)

	if plan.cycle_tables:
		st.warning(
			"Cycle de dépendances détecté sur : " + ", ".join(f"`{table_name}`" for table_name in plan.cycle_tables)
			+ ". L'ordre final est un best effort ; validez soigneusement avant exécution."
		)

	if plan.operations:
		st.caption("Ordre d'exécution calculé pour respecter au mieux les clés étrangères détectées.")
		st.code("\n".join(operation.statement for operation in plan.operations), language="sql")
		for operation in plan.operations:
			st.caption(f"- `{operation.table_name}` : {operation.reason}")
	else:
		st.info("Aucune commande exécutable pour la sélection courante.")

	can_execute = bool(plan.operations) and not plan.missing_tables and not plan.blocked_by_dependencies
	confirm_purge = st.checkbox(
		"Je confirme vouloir vider définitivement les données des tables sélectionnées.",
		key=CONFIRM_PURGE_KEY,
	)

	if st.button(
		" Vider les tables sélectionnées",
		type="primary",
		use_container_width=True,
		disabled=not can_execute or not confirm_purge,
	):
		try:
			result = execute_table_purge(engine, plan)
		except Exception as exc:
			st.error(f"Échec du vidage : {exc}")
		else:
			for table_name in result.executed_tables:
				st.session_state[_checkbox_key(table_name)] = False
			st.session_state[CONFIRM_PURGE_KEY] = False
			st.success(
				f"Vidage terminé pour {len(result.executed_tables)} table(s). Total de lignes affectées : {result.total_rows_affected}."
			)
			st.rerun()

	protected_names = ", ".join(sorted(name for name in PROTECTED_TABLES if name.endswith("s") or name == "stock_metadata"))
	st.caption(f"Tables protégées côté IHM : `{protected_names}`.")


run_page_if_standalone(__name__, render)

"""Services d'administration DB pour l'IHM Streamlit."""
from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass
from pathlib import Path
import re
from typing import Iterable

from sqlalchemy import text
from sqlalchemy.engine import Engine

from ihm.services.pipeline_runner import PROJECT_ROOT

SQL_DIRECTORY = PROJECT_ROOT / "database" / "sql"
PROTECTED_TABLES = frozenset({
    "stock_metadata",
    "stock_bars",
    "stock_bars_daily",
    "stock_bar",
    "stock_bar_daily",
})

FUNCTIONALITY_GROUP_ORDER: tuple[str, ...] = (
    "Marché / Référentiel titres",
    "News / Sentiment",
    "ML / Modèles",
    "Risk / Portefeuille",
    "Exécution broker",
    "Corporate Actions",
    "Autres / non classées",
)

FUNCTIONALITY_TABLES: dict[str, tuple[str, ...]] = {
    "Marché / Référentiel titres": (
        "stock_bars",
        "stock_bars_daily",
        "stock_metadata",
        "stock_scores",
        "cleaning_audit_log",
    ),
    "News / Sentiment": (
        "news_raw",
        "news_sentiment",
        "news_ticker_map",
        "news_ingestion_checkpoint",
        "macro_event_audit",
        "ticker_daily_sentiment_features",
        "sector_daily_sentiment_features",
    ),
    "ML / Modèles": (
        "model_registry",
        "model_training_run",
        "model_metrics",
        "model_predictions",
    ),
    "Risk / Portefeuille": (
        "risk_decisions",
        "portfolio_targets",
        "portfolio_cash_ledger",
    ),
    "Exécution broker": (
        "execution_runs",
        "execution_orders",
        "execution_fills",
        "execution_events",
        "broker_positions_snapshots",
    ),
    "Corporate Actions": (
        "corporate_actions_events",
        "corporate_actions_applications",
    ),
}

ADDITIONAL_KNOWN_TABLES = frozenset(
    {
        table_name
        for tables in FUNCTIONALITY_TABLES.values()
        for table_name in tables
    }
)

_TABLE_TOKEN_PATTERNS: tuple[re.Pattern[str], ...] = (
    re.compile(r"\bTRUNCATE\s+TABLE\s+([`\w.]+)", re.IGNORECASE),
    re.compile(r"\bDELETE\s+FROM\s+([`\w.]+)", re.IGNORECASE),
    re.compile(r"\bALTER\s+TABLE\s+([`\w.]+)", re.IGNORECASE),
)


@dataclass(frozen=True, slots=True)
class DatabaseTableSnapshot:
    existing_tables: tuple[str, ...]
    row_estimates: dict[str, int | None]
    foreign_key_pairs: tuple[tuple[str, str], ...]


@dataclass(frozen=True, slots=True)
class TableCatalogEntry:
    table_name: str
    functionality_group: str
    exists_in_database: bool
    protected: bool
    row_estimate: int | None


@dataclass(frozen=True, slots=True)
class TablePurgeOperation:
    table_name: str
    statement: str
    strategy: str
    reason: str


@dataclass(frozen=True, slots=True)
class TablePurgePlan:
    selected_tables: tuple[str, ...]
    operations: tuple[TablePurgeOperation, ...]
    protected_tables: tuple[str, ...]
    missing_tables: tuple[str, ...]
    blocked_by_dependencies: dict[str, tuple[str, ...]]
    cycle_tables: tuple[str, ...]


@dataclass(frozen=True, slots=True)
class TablePurgeResult:
    executed_tables: tuple[str, ...]
    executed_statements: tuple[str, ...]
    total_rows_affected: int


def _normalize_table_name(value: str) -> str:
    cleaned = value.strip().strip("`").strip()
    if not cleaned:
        return ""
    return cleaned.split(".")[-1].strip("`").lower()


def discover_tables_from_sql_directory(sql_directory: Path = SQL_DIRECTORY) -> set[str]:
    tables: set[str] = set()
    if not sql_directory.exists():
        return tables

    for path in sorted(sql_directory.glob("*.sql")):
        content = path.read_text(encoding="utf-8", errors="replace")
        for pattern in _TABLE_TOKEN_PATTERNS:
            for match in pattern.finditer(content):
                normalized = _normalize_table_name(match.group(1))
                if normalized:
                    tables.add(normalized)
    return tables


def _classify_table(table_name: str) -> str:
    for group_name, tables in FUNCTIONALITY_TABLES.items():
        if table_name in tables:
            return group_name

    if table_name.startswith("news_") or table_name.endswith("_sentiment_features"):
        return "News / Sentiment"
    if table_name.startswith("model_"):
        return "ML / Modèles"
    if table_name.startswith("execution_") or table_name.startswith("broker_"):
        return "Exécution broker"
    if table_name.startswith("corporate_actions_"):
        return "Corporate Actions"
    if table_name.startswith("portfolio_") or table_name.startswith("risk_"):
        return "Risk / Portefeuille"
    if table_name.startswith("stock_") or table_name.startswith("cleaning_"):
        return "Marché / Référentiel titres"
    return "Autres / non classées"


def load_database_table_snapshot(engine: Engine) -> DatabaseTableSnapshot:
    with engine.connect() as conn:
        rows = conn.execute(
            text(
                """
                SELECT table_name, table_rows
                FROM information_schema.tables
                WHERE table_schema = DATABASE()
                ORDER BY table_name
                """
            )
        ).fetchall()
        relations = conn.execute(
            text(
                """
                SELECT DISTINCT table_name AS child_table, referenced_table_name AS parent_table
                FROM information_schema.key_column_usage
                WHERE table_schema = DATABASE()
                  AND referenced_table_name IS NOT NULL
                ORDER BY child_table, parent_table
                """
            )
        ).fetchall()

    existing_tables = tuple(sorted(_normalize_table_name(str(row[0])) for row in rows if row[0]))
    row_estimates = {
        _normalize_table_name(str(row[0])): (int(row[1]) if row[1] is not None else None)
        for row in rows
        if row[0]
    }
    foreign_key_pairs = tuple(
        (
            _normalize_table_name(str(row[0])),
            _normalize_table_name(str(row[1])),
        )
        for row in relations
        if row[0] and row[1]
    )
    return DatabaseTableSnapshot(
        existing_tables=existing_tables,
        row_estimates=row_estimates,
        foreign_key_pairs=foreign_key_pairs,
    )


def list_grouped_tables(snapshot: DatabaseTableSnapshot) -> dict[str, list[TableCatalogEntry]]:
    declared_tables = discover_tables_from_sql_directory()
    all_tables = set(snapshot.existing_tables) | declared_tables | set(ADDITIONAL_KNOWN_TABLES)

    grouped: dict[str, list[TableCatalogEntry]] = {group_name: [] for group_name in FUNCTIONALITY_GROUP_ORDER}
    existing_set = set(snapshot.existing_tables)
    for table_name in sorted(all_tables):
        group_name = _classify_table(table_name)
        grouped.setdefault(group_name, []).append(
            TableCatalogEntry(
                table_name=table_name,
                functionality_group=group_name,
                exists_in_database=table_name in existing_set,
                protected=table_name in PROTECTED_TABLES,
                row_estimate=snapshot.row_estimates.get(table_name),
            )
        )

    return {group_name: entries for group_name, entries in grouped.items() if entries}


def _build_dependency_maps(
    foreign_key_pairs: Iterable[tuple[str, str]],
) -> tuple[dict[str, set[str]], dict[str, set[str]]]:
    parents_by_child: dict[str, set[str]] = defaultdict(set)
    children_by_parent: dict[str, set[str]] = defaultdict(set)
    for child_table, parent_table in foreign_key_pairs:
        child = _normalize_table_name(child_table)
        parent = _normalize_table_name(parent_table)
        if not child or not parent:
            continue
        parents_by_child[child].add(parent)
        children_by_parent[parent].add(child)
    return parents_by_child, children_by_parent


def _topological_delete_order(
    selected_tables: set[str],
    foreign_key_pairs: Iterable[tuple[str, str]],
) -> tuple[list[str], list[str]]:
    graph: dict[str, set[str]] = {table_name: set() for table_name in selected_tables}
    indegree: dict[str, int] = {table_name: 0 for table_name in selected_tables}

    for child_table, parent_table in foreign_key_pairs:
        child = _normalize_table_name(child_table)
        parent = _normalize_table_name(parent_table)
        if child not in selected_tables or parent not in selected_tables or child == parent:
            continue
        if parent in graph[child]:
            continue
        graph[child].add(parent)
        indegree[parent] += 1

    queue: deque[str] = deque(sorted(table_name for table_name, degree in indegree.items() if degree == 0))
    ordered: list[str] = []
    while queue:
        table_name = queue.popleft()
        ordered.append(table_name)
        for parent in sorted(graph[table_name]):
            indegree[parent] -= 1
            if indegree[parent] == 0:
                queue.append(parent)

    cycle_tables = sorted(table_name for table_name in selected_tables if table_name not in ordered)
    if cycle_tables:
        ordered.extend(cycle_tables)
    return ordered, cycle_tables


def build_table_purge_plan(
    selected_tables: Iterable[str],
    snapshot: DatabaseTableSnapshot,
) -> TablePurgePlan:
    normalized_selection: list[str] = []
    seen: set[str] = set()
    for table_name in selected_tables:
        normalized = _normalize_table_name(table_name)
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        normalized_selection.append(normalized)

    protected_tables = tuple(sorted(table_name for table_name in normalized_selection if table_name in PROTECTED_TABLES))
    existing_set = set(snapshot.existing_tables)
    requested_tables = [table_name for table_name in normalized_selection if table_name not in PROTECTED_TABLES]
    missing_tables = tuple(sorted(table_name for table_name in requested_tables if table_name not in existing_set))
    selectable_tables = {table_name for table_name in requested_tables if table_name in existing_set}

    parents_by_child, children_by_parent = _build_dependency_maps(snapshot.foreign_key_pairs)
    blocked_by_dependencies = {
        table_name: tuple(sorted(child_table for child_table in children_by_parent.get(table_name, set()) if child_table not in selectable_tables))
        for table_name in sorted(selectable_tables)
        if any(child_table not in selectable_tables for child_table in children_by_parent.get(table_name, set()))
    }

    if blocked_by_dependencies:
        return TablePurgePlan(
            selected_tables=tuple(normalized_selection),
            operations=(),
            protected_tables=protected_tables,
            missing_tables=missing_tables,
            blocked_by_dependencies=blocked_by_dependencies,
            cycle_tables=(),
        )

    ordered_tables, cycle_tables = _topological_delete_order(selectable_tables, snapshot.foreign_key_pairs)
    operations = tuple(
        TablePurgeOperation(
            table_name=table_name,
            statement=f"DELETE FROM `{table_name}`;",
            strategy="delete",
            reason=(
                "Suppression ordonnée pour respecter les clés étrangères."
                if parents_by_child.get(table_name) or children_by_parent.get(table_name)
                else "Suppression simple de toutes les lignes de la table."
            ),
        )
        for table_name in ordered_tables
    )
    return TablePurgePlan(
        selected_tables=tuple(normalized_selection),
        operations=operations,
        protected_tables=protected_tables,
        missing_tables=missing_tables,
        blocked_by_dependencies={},
        cycle_tables=tuple(cycle_tables),
    )


def execute_table_purge(engine: Engine, plan: TablePurgePlan) -> TablePurgeResult:
    if plan.missing_tables:
        raise ValueError(f"Tables introuvables en base : {', '.join(plan.missing_tables)}")
    if plan.blocked_by_dependencies:
        raise ValueError("Certaines tables sélectionnées sont bloquées par des tables dépendantes non sélectionnées.")

    executed_tables: list[str] = []
    executed_statements: list[str] = []
    total_rows_affected = 0
    with engine.begin() as conn:
        for operation in plan.operations:
            result = conn.execute(text(operation.statement))
            executed_tables.append(operation.table_name)
            executed_statements.append(operation.statement)
            rowcount = result.rowcount if result.rowcount is not None and result.rowcount >= 0 else 0
            total_rows_affected += int(rowcount)

    return TablePurgeResult(
        executed_tables=tuple(executed_tables),
        executed_statements=tuple(executed_statements),
        total_rows_affected=total_rows_affected,
    )

from ihm.pages import db_admin


def test_pages_db_admin_importable() -> None:
    assert hasattr(db_admin, "__doc__")
